// TCB1 binary browse dataset — client decoder + transpose session
// (Tower optimization Phase 2A, FILTER-REVAMP-DESIGN.md §12).
//
// The browse stream's third source: beside the JSON browse pages, the
// catalog also publishes as a columnar binary dataset (TCB1 shards +
// a TCD1 dictionary file + a TCU1 curated-bitset file), generated by
// scripts/build-tcb1.mjs from the same canonical catalog-index shards
// and parity-proven record-for-record against the JSON. This module
// turns one decoded shard into the EXACT payload shape
// catalog-core.js's createTransposeSession produces from a JSON page
// — same dedupe contract (first occurrence of an artifact_id wins,
// verified byte-wise against a CatalogIdIndex over retained id
// bytes), same session-local dictionary codes, same `fresh` lists —
// so commitTransposedChunk (catalog.js) commits a binary chunk into
// the column store indistinguishably from a JSON one, and every
// downstream consumer (filter engine, derivations, sort orders) sees
// the identical columnar state either way.
//
// Format specs: TCB1/TCD1 in tower-perf-data/FORMAT.md (stage 1);
// TCU1 in scripts/build-tcb1.mjs. All string decodes use
// ignoreBOM: true — 264 catalog strings carry a genuine leading
// U+FEFF that a default TextDecoder silently strips (JSON.parse does
// not), which would break parity on exactly those records.
import { CatalogIdIndex, TRANSPOSE_COLUMNS, fnv1aBytes } from "./catalog-core.js";

export const TCB1_INT32_NULL_YEAR = -2147483648;

const textDecoder = new TextDecoder("utf-8", { ignoreBOM: true });

const SHARD_SECTIONS = [
  "id_offsets", "id_blob", "title_offsets", "title_blob", "creator_codes",
  "year_i32", "year_str_rows", "year_str_offsets", "year_str_blob",
  "collection_codes", "download_codes", "rights_codes", "format_codes",
];

// ---- TCD1 dictionary ------------------------------------------------
// Returns { creator: {nullable, count, offsets, blob}, ... } where
// offsets/blob are views over the input buffer (zero-copy: the dict
// buffer stays resident in the worker for the stream's lifetime and
// values are decoded on first use only).
export function parseTcb1Dict(buf) {
  const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  if (
    buf[0] !== 0x54 || buf[1] !== 0x43 || buf[2] !== 0x44 || buf[3] !== 0x31
  ) {
    throw new Error("tcb1 dict: bad magic");
  }
  const version = dv.getUint16(4, true);
  if (version !== 1) throw new Error(`tcb1 dict: unsupported version ${version}`);
  const fieldCount = dv.getUint16(6, true);
  let p = 8;
  const dict = {};
  for (let i = 0; i < fieldCount; i++) {
    const nameLen = dv.getUint8(p); p += 1;
    const name = textDecoder.decode(buf.subarray(p, p + nameLen)); p += nameLen;
    const nullable = dv.getUint8(p); p += 1;
    const count = dv.getUint32(p, true); p += 4;
    p += (8 - (p % 8)) % 8;
    const offsets = new Uint32Array(buf.buffer, buf.byteOffset + p, count + 1);
    p += (count + 1) * 4;
    const blobLen = offsets[count];
    const blob = buf.subarray(p, p + blobLen); p += blobLen;
    dict[name] = { nullable: !!nullable, count, offsets, blob };
  }
  return dict;
}

// The raw dictionary value for a code (string, or null for the null
// slot of a nullable dictionary). Types match the JSON records
// exactly: dictionary values are always strings or null.
export function tcb1DictValue(dict, field, code) {
  const d = dict[field];
  if (d.nullable && code === 0) return null;
  const idx = d.nullable ? code - 1 : code;
  return textDecoder.decode(d.blob.subarray(d.offsets[idx], d.offsets[idx + 1]));
}

// ---- TCB1 shard ------------------------------------------------------
// Section views over the (already checksum-verified) shard buffer.
export function parseTcb1Shard(buf) {
  const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  if (
    buf[0] !== 0x54 || buf[1] !== 0x43 || buf[2] !== 0x42 || buf[3] !== 0x31
  ) {
    throw new Error("tcb1 shard: bad magic");
  }
  const version = dv.getUint16(4, true);
  if (version !== 1) throw new Error(`tcb1 shard: unsupported version ${version}`);
  const recordCount = dv.getUint32(8, true);
  const shardIndex = dv.getUint32(12, true);
  const sec = {};
  let p = 16;
  for (const name of SHARD_SECTIONS) {
    sec[name] = { offset: dv.getUint32(p, true), length: dv.getUint32(p + 4, true) };
    p += 8;
  }
  const view = (name, Type) =>
    new Type(buf.buffer, buf.byteOffset + sec[name].offset, sec[name].length / Type.BYTES_PER_ELEMENT);
  return {
    recordCount,
    shardIndex,
    idOffsets: view("id_offsets", Uint32Array),
    idBlob: buf.subarray(sec.id_blob.offset, sec.id_blob.offset + sec.id_blob.length),
    titleOffsets: view("title_offsets", Uint32Array),
    titleBlob: buf.subarray(sec.title_blob.offset, sec.title_blob.offset + sec.title_blob.length),
    creatorCodes: view("creator_codes", Uint32Array),
    years: view("year_i32", Int32Array),
    yearStrRows: view("year_str_rows", Uint32Array),
    yearStrOffsets: view("year_str_offsets", Uint32Array),
    yearStrBlob: buf.subarray(
      sec.year_str_blob.offset,
      sec.year_str_blob.offset + sec.year_str_blob.length
    ),
    collectionCodes: view("collection_codes", Uint8Array),
    downloadCodes: view("download_codes", Uint8Array),
    rightsCodes: view("rights_codes", Uint8Array),
    formatCodes: view("format_codes", Uint8Array),
  };
}

// ---- TCU1 curated bitsets ---------------------------------------------
// Returns [{key, label, count, bits}] in file order (the
// buildCollections order), bits a Uint32Array over catalog indices —
// bit i (LSB-first within each byte, matching the generator) is
// collection membership of catalog record i. `count` is the bitset's
// popcount: the number of catalog records the filter itself returns
// for the collection.
export function parseCuratedBitsets(buf) {
  const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  if (
    buf[0] !== 0x54 || buf[1] !== 0x43 || buf[2] !== 0x55 || buf[3] !== 0x31
  ) {
    throw new Error("tcu1: bad magic");
  }
  const version = dv.getUint16(4, true);
  if (version !== 1) throw new Error(`tcu1: unsupported version ${version}`);
  const count = dv.getUint32(8, true);
  const total = dv.getUint32(12, true);
  const bitsetBytes = Math.ceil(total / 8);
  let p = 16;
  const out = [];
  for (let e = 0; e < count; e++) {
    const keyLen = dv.getUint8(p); p += 1;
    const key = textDecoder.decode(buf.subarray(p, p + keyLen)); p += keyLen;
    const labelLen = dv.getUint8(p); p += 1;
    const label = textDecoder.decode(buf.subarray(p, p + labelLen)); p += labelLen;
    const n = dv.getUint32(p, true); p += 4;
    const raw = buf.subarray(p, p + bitsetBytes); p += bitsetBytes;
    const bits = new Uint32Array(Math.ceil(total / 32));
    new Uint8Array(bits.buffer).set(raw);
    out.push({ key, label, count: n, bits });
  }
  return { total, collections: out };
}

// ---- Transpose session over shards -------------------------------------
// Mirrors createTransposeSession (catalog-core.js) exactly, sourcing
// records from parsed shards instead of JSON objects: global TCB1
// dictionary codes are translated to session-local codes through the
// decoded dictionary values (decoded once per distinct value), years
// are reconstructed as their raw three-typed values (number / string
// / null), and id/title bytes are copied verbatim from the shard
// sections — byte-identical to the JSON path's encodeInto output by
// construction (both normalize unpaired surrogates to U+FFFD).
export function createTcb1Session(dict, expectedCount = 0) {
  const dicts = {};
  for (const [key] of TRANSPOSE_COLUMNS) {
    dicts[key] = { map: new Map(), values: [] };
  }
  const retained = [];
  const chunkOf = [];
  let count = 0;
  const bytesAt = (i) => {
    const c = chunkOf[i];
    if (!c) return null;
    const local = i - c.start;
    return [c.idBytes, c.idOff[local], c.idOff[local + 1]];
  };
  let index = new CatalogIdIndex(null, expectedCount || 0, bytesAt);

  function dictCodeLocal(key, v, fresh) {
    const d = dicts[key];
    let code = d.map.get(v);
    if (code === undefined) {
      code = d.values.length;
      d.map.set(v, code);
      d.values.push(v);
      fresh[key].push(v);
    }
    return code;
  }

  // Global-code translation tables (global code -> session-local
  // code), built lazily: the creator dictionary has ~1.07M entries,
  // of which a stream prefix touches only the ones it contains.
  const creatorXlate = new Int32Array(dict.creator.count + 1).fill(-1);
  const smallXlate = {};
  for (const field of ["collection", "download_status", "rights_status", "format"]) {
    smallXlate[field] = new Int32Array(dict[field].count).fill(-1);
  }
  function creatorLocal(globalCode, fresh) {
    let local = creatorXlate[globalCode];
    if (local < 0) {
      local = dictCodeLocal("creator", tcb1DictValue(dict, "creator", globalCode), fresh);
      creatorXlate[globalCode] = local;
    }
    return local;
  }
  function smallLocal(field, key, globalCode, fresh) {
    const x = smallXlate[field];
    let local = x[globalCode];
    if (local < 0) {
      local = dictCodeLocal(key, tcb1DictValue(dict, field, globalCode), fresh);
      x[globalCode] = local;
    }
    return local;
  }
  function yearRaw(shard, i) {
    const yv = shard.years[i];
    if (yv !== TCB1_INT32_NULL_YEAR) return yv;
    const rows = shard.yearStrRows;
    let lo = 0, hi = rows.length - 1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (rows[mid] === i) {
        return textDecoder.decode(
          shard.yearStrBlob.subarray(shard.yearStrOffsets[mid], shard.yearStrOffsets[mid + 1])
        );
      }
      if (rows[mid] < i) lo = mid + 1; else hi = mid - 1;
    }
    return null;
  }

  function transposeShard(shard, pageCursor = 0) {
    const total = shard.recordCount;
    const fresh = {};
    for (const [key] of TRANSPOSE_COLUMNS) fresh[key] = [];
    const emptyCodes = () => {
      const codes = {};
      for (const [key, , ctor] of TRANSPOSE_COLUMNS) codes[key] = new ctor(0);
      return codes;
    };
    if (!total) {
      retained.push({
        pageCursor, start: count, n: 0,
        idBytes: new Uint8Array(0), idOff: new Uint32Array(1),
      });
      return {
        n: 0,
        idBytes: new Uint8Array(0), idOff: new Uint32Array(1),
        titleBytes: new Uint8Array(0), titleOff: new Uint32Array(1),
        codes: emptyCodes(), fresh,
      };
    }
    // Dedupe, identical to the JSON transpose: first occurrence wins,
    // within the shard (byte-keyed scratch map — no id string is ever
    // materialized) and against everything the session has accepted
    // (the byte-mode index over retained id bytes).
    const seenLocal = new Map(); // fnv1aBytes(id) -> [idBytes, ...]
    const accepted = [];
    const { idOffsets, idBlob } = shard;
    for (let i = 0; i < total; i++) {
      const s = idOffsets[i];
      const e = idOffsets[i + 1];
      if (e === s) continue; // no id — the JSON path skips id-less records
      const idBytes = idBlob.subarray(s, e);
      const h = fnv1aBytes(idBytes);
      const bucket = seenLocal.get(h);
      if (bucket) {
        let dup = false;
        for (const b of bucket) {
          if (b.length === idBytes.length) {
            let same = true;
            for (let k = 0; k < b.length; k++) if (b[k] !== idBytes[k]) { same = false; break; }
            if (same) { dup = true; break; }
          }
        }
        if (dup) continue;
      }
      if (index.getBytes(idBytes) !== undefined) continue;
      if (bucket) bucket.push(idBytes); else seenLocal.set(h, [idBytes]);
      accepted.push(i);
    }
    const n = accepted.length;
    const start = count;
    const idOff = new Uint32Array(n + 1);
    const titleOff = new Uint32Array(n + 1);
    let idLen = 0;
    let titleLen = 0;
    for (let j = 0; j < n; j++) {
      const i = accepted[j];
      idOff[j + 1] = (idLen += idOffsets[i + 1] - idOffsets[i]);
      titleOff[j + 1] = (titleLen += shard.titleOffsets[i + 1] - shard.titleOffsets[i]);
    }
    const idBytes = new Uint8Array(idLen);
    const titleBytes = new Uint8Array(titleLen);
    for (let j = 0; j < n; j++) {
      const i = accepted[j];
      idBytes.set(idBlob.subarray(idOffsets[i], idOffsets[i + 1]), idOff[j]);
      titleBytes.set(
        shard.titleBlob.subarray(shard.titleOffsets[i], shard.titleOffsets[i + 1]),
        titleOff[j]
      );
    }
    const codes = {};
    for (const [key, , ctor] of TRANSPOSE_COLUMNS) codes[key] = new ctor(n);
    for (let j = 0; j < n; j++) {
      const i = accepted[j];
      codes.creator[j] = creatorLocal(shard.creatorCodes[i], fresh);
      codes.year[j] = dictCodeLocal("year", yearRaw(shard, i), fresh);
      codes.coll[j] = smallLocal("collection", "coll", shard.collectionCodes[i], fresh);
      codes.fmt[j] = smallLocal("format", "fmt", shard.formatCodes[i], fresh);
      codes.rights[j] = smallLocal("rights_status", "rights", shard.rightsCodes[i], fresh);
      codes.dl[j] = smallLocal("download_status", "dl", shard.downloadCodes[i], fresh);
    }
    const chunk = {
      pageCursor, start, n,
      idBytes: idBytes.slice(), idOff: idOff.slice(),
    };
    retained.push(chunk);
    for (let j = 0; j < n; j++) chunkOf.push(chunk);
    for (let j = 0; j < n; j++) {
      const i = accepted[j];
      index.addBytes(start + j, idBlob.subarray(idOffsets[i], idOffsets[i + 1]));
    }
    count += n;
    index.builtLen = count;
    return { n, idBytes, idOff, titleBytes, titleOff, codes, fresh };
  }

  // Same contract as the JSON session's resetTo (see catalog-core.js).
  function resetTo(serverCursor) {
    let keep = 0;
    while (keep < retained.length && retained[keep].pageCursor < serverCursor) {
      keep++;
    }
    retained.length = keep;
    chunkOf.length = 0;
    count = 0;
    for (const c of retained) {
      c.start = count;
      for (let j = 0; j < c.n; j++) chunkOf.push(c);
      count += c.n;
    }
    index = new CatalogIdIndex(null, expectedCount || count, bytesAt);
    index.syncToBytes(count);
    index.builtLen = count;
  }

  return {
    transposeShard,
    resetTo,
    get count() { return count; },
  };
}
